def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a solid, nonzero separator row.
    for r, row in enumerate(grid):
        if row[0] != 0 and all(x == row[0] for x in row):
            top, bottom = grid[:r], grid[r + 1:]
            n = min(len(top), len(bottom))
            return [
                [2 if top[i][c] != 0 and bottom[i][c] != 0 else 0
                 for c in range(w)]
                for i in range(n)
            ]

    # Otherwise find a solid, nonzero separator column.
    for c in range(w):
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
            left, right = c, c + 1
            n = min(left, w - right)
            return [
                [2 if grid[r][j] != 0 and grid[r][right + j] != 0 else 0
                 for j in range(n)]
                for r in range(h)
            ]

    return []
